+        boolean result = false;
+        if (ignoreAbstractMethods && ast.getType() == TokenTypes.PARAMETER_DEF) {
+            final DetailAST method = ast.getParent().getParent();
+            if (method.getType() == TokenTypes.METHOD_DEF) {
