+                if (info.getElasticsearchVersion().before(Version.CURRENT)) {
+                    this.terminal.println(
+                        Terminal.Verbosity.VERBOSE,
+                        String.format(
+                            Locale.ROOT,
+                            "Official plugin [%s] is out-of-date (%s versus %s), upgrading",
+                            eachPluginId,
+                            info.getElasticsearchVersion(),
+                            Version.CURRENT
+                        )
