+        );
+
+    }
+
+    public void testEmbeddedValue() throws IOException {
+
+        assertXContentMatches(
+            "{\"test\":{\"with\":{\"dots\":\"value\"}},\"nodots\":\"value2\"}",
+            "{\"test.with.dots\":\"value\",\"nodots\":\"value2\"}"
