+                return;
+            }
+
+            try {
+                // Get first or last child, which is an EXPR, then get the argument itself
+                final String maxStr = argListAst.getLastChild().getFirstChild().getText();
+                min = 0;
+                max = Integer.parseInt(maxStr);
+            } catch (NumberFormatException e) {
