+                    if (switchMethodName.equals("randomInt")) {
+                        log(caseAst, SWITCH_RANDOM_INT_MSG_KEY, value, switchMethodName, max);
+                    } else {
+                        log(caseAst, SWITCH_BETWEEN_MSG_KEY, value, switchMethodName, min, max);
